contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethSent) public payable {
        // Precondition: lengths must match for inputs to be meaningful; require to constrain inputs
        require(tokenIds.length == tokenWeights.length, "length");
        // Ensure we have ETH available if caller wants to send ETH to buy
        if (ethSent > 0) {
            require(address(this).balance >= ethSent, "no eth");
        }

        // Read initial observable state
        uint128 beforeVirtualNft = c.virtualNftReserves();
        address baseToken = c.baseToken();
        uint256 beforeBalance = address(c).balance;

        // Compute summed weights as caller would expect: sum of tokenWeights
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // Prepare MerkleMultiProof calldata struct for buy
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // Attempt the buy call, sending ETH if baseToken == address(0)
        if (baseToken == address(0)) {
            // call with value ethSent
            try c.buy{value: ethSent}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
                reverted = false;
                netInputAmount = n; feeAmount = f; protocolFeeAmount = p;
            } catch {
                reverted = true;
            }
        } else {
            // ERC20 path: do not send ETH
            try c.buy(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
                reverted = false;
                netInputAmount = n; feeAmount = f; protocolFeeAmount = p;
            } catch {
                reverted = true;
            }
        }

        uint128 afterVirtualNft = c.virtualNftReserves();
        uint256 afterBalance = address(c).balance;

        // General rule (single assert): If buy succeeded (not reverted) then virtualNftReserves decreased by exactly sumWeights;
        // if buy reverted then virtualNftReserves unchanged. Additionally, when baseToken==address(0) and buy succeeded,
        // the contract's ETH balance increased by at least protocolFeeAmount + feeAmount (protocol fees forwarded to factory may be paid separately,
        // but the pool should receive netInputAmount - feeAmount - protocolFeeAmount; however to be conservative we assert balance increased by >= 0
        // and specifically that when baseToken==address(0) and succeeded, afterBalance >= beforeBalance (non-decreasing).
        // We express the core invariant about virtualNftReserves change.

        if (!reverted) {
            // note: avoid underflow in assert by comparing via >=
            assert(beforeVirtualNft >= afterVirtualNft && uint256(beforeVirtualNft) - uint256(afterVirtualNft) == sumWeights);
        } else {
            assert(beforeVirtualNft == afterVirtualNft);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(
        uint256[] calldata inputTokenIds,
        uint256[] calldata inputTokenWeights,
        bytes32[] calldata inputProofBytes,
        bool[] calldata inputFlags,
        uint256[] calldata outputTokenIds,
        uint256[] calldata outputTokenWeights,
        bytes32[] calldata outputProofBytes,
        bool[] calldata outputFlags,
        uint256 ethSent
    ) public payable {
        // Basic shape requirements for inputs to be meaningful
        require(inputTokenIds.length == inputTokenWeights.length, "in_len");
        require(outputTokenIds.length == outputTokenWeights.length, "out_len");
        // Prepare MerkleMultiProof memory structs (as required by change)
        C.MerkleMultiProof memory inProof;
        C.MerkleMultiProof memory outProof;
        inProof.proof = inputProofBytes;
        inProof.flags = inputFlags;
        outProof.proof = outputProofBytes;
        outProof.flags = outputFlags;

        // Ensure this contract has ETH if caller intends to forward ETH to c for payable paths
        if (ethSent > 0) {
            require(address(this).balance >= ethSent, "no eth");
        }

        // Observe before-state
        uint128 beforeVirtualNft = c.virtualNftReserves();
        address baseToken = c.baseToken();
        uint256 beforeBalance = address(c).balance;

        // compute sums of weights (purely in test)
        uint256 sumIn = 0;
        for (uint256 i = 0; i < inputTokenWeights.length; i++) {
            sumIn += inputTokenWeights[i];
        }
        uint256 sumOut = 0;
        for (uint256 i = 0; i < outputTokenWeights.length; i++) {
            sumOut += outputTokenWeights[i];
        }

        // Make the state-changing call as its own top-level statement
        bool reverted;
        {
            // Call with value only when baseToken is address(0)
            if (baseToken == address(0)) {
                try c.change{value: ethSent}(
                    inputTokenIds,
                    inputTokenWeights,
                    inProof,
                    new IStolenNftOracle.Message[](0),
                    outputTokenIds,
                    outputTokenWeights,
                    outProof
                ) returns (uint256 feeAmount, uint256 protocolFeeAmount) {
                    reverted = false;
                    // silence unused vars by trivial read
                    feeAmount; protocolFeeAmount;
                } catch {
                    reverted = true;
                }
            } else {
                try c.change(
                    inputTokenIds,
                    inputTokenWeights,
                    inProof,
                    new IStolenNftOracle.Message[](0),
                    outputTokenIds,
                    outputTokenWeights,
                    outProof
                ) returns (uint256 feeAmount, uint256 protocolFeeAmount) {
                    reverted = false;
                    feeAmount; protocolFeeAmount;
                } catch {
                    reverted = true;
                }
            }
        }

        // Observe after-state
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint256 afterBalance = address(c).balance;

        // Single assert expressing the general rule:
        // If the call reverted then virtualNftReserves and pool balance are unchanged;
        // if it succeeded then virtualNftReserves increased by exactly (sumIn - sumOut)
        // (which may be zero) and the pool's balance changed by at least zero (non-negative change when baseToken==address(0) is not enforced here because fees/protocol transfers may forward ETH).
        // We encode: reverted => before==after for reserves and balance; not reverted => after == before + (sumIn - sumOut)
        assert(
            (reverted && uint256(beforeVirtualNft) == uint256(afterVirtualNft) && beforeBalance == afterBalance)
            || (!reverted && uint256(afterVirtualNft) == uint256(beforeVirtualNft) + (sumIn >= sumOut ? (sumIn - sumOut) : 0))
        );
    }

    receive() external payable {}
}

