contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public test function: try to call buy and assert the invariant about virtual reserves when call succeeds
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofBytes, bool[] calldata flags, uint256 ethAmount) public payable {
        // We need to provide a MerkleMultiProof struct for buy. The contract expects MerkleMultiProof calldata with .proof and .flags.
        // Build a MerkleMultiProof calldata-compatible memory copy by creating local memory arrays and copying calldata in.
        // However, since buy's proof parameter is a struct with calldata arrays, we can forward calldata arrays directly by calling c.buy with a constructed struct in memory.

        // Read before-values via view functions/public getters
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();

        // Prepare MerkleMultiProof in memory
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](proofBytes.length);
        for (uint i = 0; i < proofBytes.length; i++) proof.proof[i] = proofBytes[i];
        proof.flags = new bool[](flags.length);
        for (uint i = 0; i < flags.length; i++) proof.flags[i] = flags[i];

        // Attempt the buy call; capture whether it reverted and any returned values when it succeeds
        bool didRevert = false;
        uint256 netInputAmount = 0;
        uint256 feeAmount = 0;
        uint256 protocolFeeAmount = 0;

        // If sending ETH, ensure this contract has enough balance to forward; caller sends msg.value to this contract when invoking run
        if (ethAmount > 0) {
            require(address(this).balance >= ethAmount, "insufficient balance to forward ETH");
        }

        try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            didRevert = true;
        }

        // Read after-values
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();

        // Compute sum of weights (in uint256 to avoid overflow in sum)
        uint256 sumWeights = 0;
        for (uint i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // General rule: if buy did not revert then virtualBaseTokenReserves increased by (netInputAmount - feeAmount - protocolFeeAmount)
        // and virtualNftReserves decreased by sumWeights. If buy reverted then state must be unchanged (i.e., before==after)
        // We assert that one of these two cases holds.
        assert(
            (!didRevert &&
                // check increment of virtualBaseTokenReserves: cast to uint256 to avoid underflow in comparison
                uint256(afterVirtualBase) == uint256(beforeVirtualBase) + (netInputAmount - feeAmount - protocolFeeAmount) &&
                // check decrement of virtualNftReserves
                uint256(afterVirtualNft) + sumWeights == uint256(beforeVirtualNft)
            ) ||
            (didRevert && uint256(afterVirtualBase) == uint256(beforeVirtualBase) && uint256(afterVirtualNft) == uint256(beforeVirtualNft))
        );
    }

    // allow receiving ETH forwarded by tests
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Test calls sell and asserts that on success the returned netOutputAmount equals the computed netOutputAmount
    // from sellQuote for the same weight sum; we restrict to baseToken == address(0) case to observe ETH flow.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofBytes, bool[] calldata flags) public payable {
        require(tokenIds.length == tokenWeights.length, "len");
        // We restrict to pools that use native ETH (baseToken == address(0)) so we can observe address(c).balance changes
        require(c.baseToken() == address(0), "not eth pool");

        // compute sum of weights locally (same way as contract would)
        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }

        // Build MerkleMultiProof in memory
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](proofBytes.length);
        for (uint256 i = 0; i < proofBytes.length; i++) proof.proof[i] = proofBytes[i];
        proof.flags = new bool[](flags.length);
        for (uint256 i = 0; i < flags.length; i++) proof.flags[i] = flags[i];

        // Read observable before-state: contract ETH balance
        uint256 beforeBalance = address(c).balance;

        bool didRevert = false;
        uint256 netOutput = 0;
        uint256 feeAmount = 0;
        uint256 protocolFeeAmount = 0;

        // Try to call sell; caller (this contract) must have approved/own NFTs for transfer in real scenario, but we are just checking relative relation between sellQuote and sell return when it doesn't revert.
        // Capture whether it reverts and the returned values.
        try c.sell(tokenIds, tokenWeights, proof, new IStolenNftOracle.Message[](0)) returns (uint256 n, uint256 f, uint256 p) {
            netOutput = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            didRevert = true;
        }

        uint256 afterBalance = address(c).balance;

        // Compute expected values via the public view sellQuote for the same weightSum
        (uint256 expectedNetOutput, uint256 expectedFee, uint256 expectedProtocol) = c.sellQuote(weightSum);

        // Assert a single general property:
        // If call did not revert then the returned triple matches sellQuote(weightSum) (observational equivalence),
        // and for ETH pool the contract's balance must have decreased by at most expectedNetOutput+expectedFee+expectedProtocol (it pays out netOutput and protocol fee to factory; due to royalties/other flows the balance change can be less predictable, so we only assert it did not increase).
        // If call reverted then the contract ETH balance is unchanged.
        assert(
            (!didRevert && netOutput == expectedNetOutput && feeAmount == expectedFee && protocolFeeAmount == expectedProtocol && afterBalance <= beforeBalance)
            || (didRevert && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Single-entry property test: compare sell's returned triple with sellQuote for a simple case.
    // We limit inputs to a single NFT to avoid complex merkle proofs and large loops.
    function run(uint256 tokenId, uint256 tokenWeight) public payable {
        // restrict to pools using native ETH so we can observe address(c).balance changes deterministically
        require(c.baseToken() == address(0), "not eth pool");

        // build trivial MerkleMultiProof: empty proof (works when merkleRoot == 0 or appropriate)
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        proof.flags = new bool[](0);

        // compute weightSum for one item
        uint256 weightSum = tokenWeight;

        // read observable before-state
        uint256 beforeBalance = address(c).balance;

        bool didRevert = false;
        uint256 gotNetOutput;
        uint256 gotFee;
        uint256 gotProtocol;

        // call sell and capture whether it reverts and returned values
        try c.sell(_toArray(tokenId), _toArray(tokenWeight), proof, new IStolenNftOracle.Message[](0)) returns (uint256 n, uint256 f, uint256 p) {
            gotNetOutput = n;
            gotFee = f;
            gotProtocol = p;
        } catch {
            didRevert = true;
        }

        uint256 afterBalance = address(c).balance;

        // expected values from the public view
        (uint256 expNetOut, uint256 expFee, uint256 expProtocol) = c.sellQuote(weightSum);

        // Assert single general rule:
        // If sell did not revert then its returned triple equals sellQuote(weightSum) and ETH balance of c decreased (it paid out netOutput and maybe protocol fee).
        // If it reverted then c's ETH balance is unchanged.
        assert((!didRevert && gotNetOutput == expNetOut && gotFee == expFee && gotProtocol == expProtocol && afterBalance <= beforeBalance)
               || (didRevert && afterBalance == beforeBalance));
    }

    // helper to create single-element uint256[] without external calls
    function _toArray(uint256 v) internal pure returns (uint256[] memory a) {
        a = new uint256[](1);
        a[0] = v;
    }

    receive() external payable {}
}

