        uint256 beforeVirtualNft = c.virtualNftReserves();
        uint256 beforeBalance = address(c).balance;

        // decode proofBytes into the MerkleMultiProof calldata shape: first 32 = proof length (n), next n*32 = proof elements,
        // then 32 = flags length (m), then m bytes packed as bools each in a 32-byte slot. We'll construct memory arrays and call.
        bytes32[] memory proof;
        bool[] memory flags;
        {
            // Minimal defensive parsing: if proofBytes is empty assume empty proof and flags
            if (proofBytes.length == 0) {
                proof = new bytes32[](0);
                flags = new bool[](0);
            } else {
                // layout: uint256 n, then n*bytes32, then uint256 m, then m bytes32 where each is 0 or 1
                // require the bytes length consistent
                if (proofBytes.length < 32) {
                    proof = new bytes32[](0);
                    flags = new bool[](0);
                } else {
                    uint256 offset = 0;
                    uint256 n;
                    assembly { n := calldataload(add(proofBytes.offset, 0)) }
                    offset += 32;
                    if (32 + n * 32 + 32 > proofBytes.length) {
                        // malformed, treat as empty
                        proof = new bytes32[](0);
                        flags = new bool[](0);
                    } else {
                        proof = new bytes32[](n);
                        for (uint256 i = 0; i < n; i++) {
                            bytes32 v;
                            assembly { v := calldataload(add(add(proofBytes.offset, 32), mul(i,32))) }
                            proof[i] = v;
                        }
                        offset += n * 32;
                        uint256 m;
                        assembly { m := calldataload(add(proofBytes.offset, offset)) }
                        offset += 32;
                        if (offset + m * 32 > proofBytes.length) {
                            flags = new bool[](0);
                        } else {
                            flags = new bool[](m);
                            for (uint256 j = 0; j < m; j++) {
                                uint256 b;
                                assembly { b := calldataload(add(add(proofBytes.offset, offset), mul(j,32))) }
                                flags[j] = (b != 0);
                            }
                        }
                    }
                }
            }
        }

        // prepare MerkleMultiProof in memory for external call
        // We need to call c.buy with MerkleMultiProof calldata; build calldata via abi.encode
        bytes memory merkleProofCalldata = abi.encode(proof, flags);

