        // We must call via ABI: c.buy(tokenIds, tokenWeights, MerkleMultiProof)
        // Use try/catch via external call on c
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, abi.decode(merkleProofCalldata, (C.MerkleMultiProof))) returns (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterVirtualNft = c.virtualNftReserves();
        uint256 afterBalance = address(c).balance;

        // Compute sum of weights conservatively (avoid under/overflow with checked arithmetic)
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // If the call succeeded (not reverted) then virtualBase should have increased by at least 0 and virtualNft decreased by sumWeights
        // and if the pool uses ETH (baseToken==address(0)) then address(c).balance should have increased by protocolFeeAmount (non-negative).
        // We cannot observe netInputAmount/fees here due to try scope, so express general invariant: if not reverted then
        // afterVirtualNft + sumWeights == beforeVirtualNft and afterVirtualBase >= beforeVirtualBase
        // Additionally, if baseToken==address(0) then afterBalance >= beforeBalance.

