            reverted
            || (
                // when success: nft reserves decreased exactly by sumWeights
                afterVirtualNft + sumWeights == beforeVirtualNft
                && afterVirtualBase >= beforeVirtualBase
                && (!baseTokenIsEth || afterBalance >= beforeBalance)
            )
        );
    }

    // allow receiving ETH forwarded from c when it refunds
    receive() external payable {}
}

