        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: sendAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // observe after values
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();

        // compute sum of weights in a safe way (uint256 then compare to fits into uint128)
        uint256 weightSum256 = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum256 += tokenWeights[i];
        }

        // The property: if buy did NOT revert, then virtualBase increased by netInput - fee - protocolFee
        // and virtualNft decreased by the weight sum. If it reverted, nothing is required.
        assert(
            reverted || (
                // check invariant using only public reads and returned values
                uint256(afterVirtualBase) == uint256(beforeVirtualBase) + (uint256(netInputAmount) - uint256(feeAmount) - uint256(protocolFeeAmount))
                && uint256(afterVirtualNft) + weightSum256 == uint256(beforeVirtualNft)
            )
        );
    }

    // allow receiving ETH for forwarding in tests
    receive() external payable {}
}
